//! Free Bosons Lie Conformal Algebra
//!
//! A Lie conformal algebra based on free bosons with a symmetric bilinear pairing.
//!
//! # Mathematical Background
//!
//! Given an R-module M with a symmetric bilinear pairing (·,·): M ⊗ M → R,
//! the free bosons Lie conformal algebra is a free R[∂]-module generated by M
//! plus a central element K with TK = 0.
//!
//! The λ-bracket is defined by:
//!
//! [v_λ w] = λ(v,w)K
//!
//! where v, w ∈ M and K is the central element.
//!
//! # References
//!
//! - Kac, V. "Vertex Algebras for Beginners" (1998)
//! - Frenkel, E. & Ben-Zvi, D. "Vertex Algebras and Algebraic Curves" (2004)
//!
//! Corresponds to sage.algebras.lie_conformal_algebras.free_bosons_lie_conformal_algebra

use rustmath_core::Ring;
use std::collections::HashMap;
use std::fmt::{self, Display};
use crate::lie_conformal_algebra::{central_valued_bracket, LieConformalAlgebra, LambdaBracket, GeneratorIndex};
use crate::graded_lie_conformal_algebra::{GradedLieConformalAlgebra, Degree, GradedLCA};
use crate::lie_conformal_algebra_element::LieConformalAlgebraElement;

/// Free Bosons Lie conformal algebra
///
/// The algebra of free bosons with a symmetric bilinear pairing (Gram matrix).
///
/// # Type Parameters
///
/// * `R` - The base ring (must be a commutative ring)
///
/// # Examples
///
/// ```
/// use rustmath_lieconformal::{FreeBosonsLieConformalAlgebra, LambdaBracket, LieConformalAlgebra};
///
/// // Create free bosons algebra with 2 generators and identity Gram matrix
/// let lca = FreeBosonsLieConformalAlgebra::new(1i64, 2, None, None);
/// assert_eq!(lca.ngens(), Some(3)); // 2 generators + 1 central element
///
/// let a0 = lca.generator(0).unwrap();
/// let a1 = lca.generator(1).unwrap();
/// let k = lca.generator(2).unwrap();
/// // [α0_λ α0] = λ (α0, α0) K = λK: only the 1st product, equal to K
/// // (Sage: lie_conformal_algebras.FreeBosons(QQ).0.bracket(...) == {1: K})
/// let br = lca.lambda_bracket(&a0, &a0);
/// assert_eq!(br.len(), 1);
/// assert_eq!(br[&1].terms(), k.terms());
/// // Orthogonal generators commute, and K is central
/// assert!(lca.lambda_bracket(&a0, &a1).is_empty());
/// assert!(lca.lambda_bracket(&k, &a0).is_empty());
///
/// // With Gram matrix [[2, 1], [1, 2]]: [α0_λ α1] = λK and [(3α0)_λ α0] = 6λK
/// let lca2 = FreeBosonsLieConformalAlgebra::new(1i64, 2, Some(vec![vec![2, 1], vec![1, 2]]), None);
/// let (b0, b1, k2) = (lca2.generator(0).unwrap(), lca2.generator(1).unwrap(), lca2.generator(2).unwrap());
/// assert_eq!(lca2.n_product(&b0, &b1, 1).terms(), k2.terms());
/// let three_b0 = b0.scalar_mul(&3);
/// assert_eq!(lca2.n_product(&three_b0, &b0, 1).terms(), k2.scalar_mul(&6).terms());
/// ```
#[derive(Clone)]
pub struct FreeBosonsLieConformalAlgebra<R: Ring> {
    /// The underlying graded structure
    graded: GradedLCA<R>,
    /// Number of non-central generators
    ngens_noncentral: usize,
    /// Gram matrix defining the symmetric bilinear pairing
    /// gram_matrix[i][j] = (α_i, α_j)
    gram_matrix: Vec<Vec<R>>,
    /// Index of the central element K
    central_index: usize,
}

impl<R: Ring + Clone + From<i64> + PartialEq> FreeBosonsLieConformalAlgebra<R> {
    /// Create a new free bosons Lie conformal algebra
    ///
    /// # Arguments
    ///
    /// * `base_ring` - The base ring
    /// * `ngens` - Number of non-central generators (default: 1)
    /// * `gram_matrix` - Symmetric Gram matrix (default: identity matrix)
    /// * `names` - Optional generator names (defaults to alpha0, alpha1, ..., K)
    ///
    /// # Panics
    ///
    /// Panics if:
    /// - The Gram matrix is not square
    /// - The Gram matrix is not symmetric
    /// - The Gram matrix dimensions don't match ngens
    ///
    /// # Examples
    ///
    /// ```
    /// use rustmath_lieconformal::FreeBosonsLieConformalAlgebra;
    ///
    /// // Identity Gram matrix
    /// let lca1 = FreeBosonsLieConformalAlgebra::new(1i64, 2, None, None);
    ///
    /// // Custom Gram matrix
    /// let gram = vec![vec![2, 1], vec![1, 2]];
    /// let lca2 = FreeBosonsLieConformalAlgebra::new(1i64, 2, Some(gram), None);
    /// ```
    pub fn new(
        base_ring: R,
        ngens: usize,
        gram_matrix: Option<Vec<Vec<R>>>,
        names: Option<Vec<String>>,
    ) -> Self {
        assert!(ngens > 0, "Number of generators must be positive");

        // Create or validate Gram matrix
        let gram = gram_matrix.unwrap_or_else(|| {
            // Default: identity matrix
            (0..ngens)
                .map(|i| {
                    (0..ngens)
                        .map(|j| if i == j { R::from(1) } else { R::from(0) })
                        .collect()
                })
                .collect()
        });

        // Validate Gram matrix
        assert_eq!(gram.len(), ngens, "Gram matrix must have ngens rows");
        for (i, row) in gram.iter().enumerate() {
            assert_eq!(row.len(), ngens, "Gram matrix must be square");

            // Check symmetry
            for j in 0..ngens {
                assert_eq!(
                    gram[i][j],
                    gram[j][i],
                    "Gram matrix must be symmetric"
                );
            }
        }

        // Central element K is the last generator
        let central_index = ngens;
        let total_gens = ngens + 1;

        // Generate default names if not provided
        let gen_names = names.unwrap_or_else(|| {
            let mut names = Vec::new();
            for i in 0..ngens {
                names.push(format!("alpha{}", i));
            }
            names.push("K".to_string());
            names
        });

        assert_eq!(
            gen_names.len(),
            total_gens,
            "Number of names must match total generators"
        );

        // All non-central generators have degree 1, K has degree 0
        let mut gen_weights = vec![Degree::int(1); ngens];
        gen_weights.push(Degree::int(0)); // Central element

        let graded = GradedLCA::new(base_ring, gen_names, gen_weights, None);

        FreeBosonsLieConformalAlgebra {
            graded,
            ngens_noncentral: ngens,
            gram_matrix: gram,
            central_index,
        }
    }

    /// Get the Gram matrix
    pub fn gram_matrix(&self) -> &[Vec<R>] {
        &self.gram_matrix
    }

    /// Get the number of non-central generators
    pub fn ngens_noncentral(&self) -> usize {
        self.ngens_noncentral
    }

    /// Get the underlying graded structure
    pub fn graded_structure(&self) -> &GradedLCA<R> {
        &self.graded
    }

    /// Get total number of generators (including central element)
    pub fn num_generators(&self) -> usize {
        self.graded.ngens()
    }

    /// Get generator names
    pub fn generator_names(&self) -> &[String] {
        self.graded.generator_names()
    }

    /// Get the bilinear pairing (α_i, α_j)
    fn get_pairing(&self, i: usize, j: usize) -> R {
        if i < self.ngens_noncentral && j < self.ngens_noncentral {
            self.gram_matrix[i][j].clone()
        } else {
            R::from(0)
        }
    }
}

/// Element type for free bosons Lie conformal algebras
pub type FreeBosonsLCAElement<R> = LieConformalAlgebraElement<R, GeneratorIndex>;

impl<R: Ring + Clone + From<i64> + PartialEq> LieConformalAlgebra<R>
    for FreeBosonsLieConformalAlgebra<R>
{
    type Element = FreeBosonsLCAElement<R>;

    fn base_ring(&self) -> &R {
        self.graded.base_ring()
    }

    fn ngens(&self) -> Option<usize> {
        Some(self.graded.ngens())
    }

    fn generator(&self, i: usize) -> Option<Self::Element> {
        if i < self.graded.ngens() {
            Some(LieConformalAlgebraElement::from_basis(
                GeneratorIndex::finite(i)
            ))
        } else {
            None
        }
    }

    fn is_abelian(&self) -> bool {
        false // Has non-trivial brackets (except when Gram matrix is zero)
    }

    fn zero(&self) -> Self::Element {
        LieConformalAlgebraElement::zero()
    }
}

impl<R: Ring + Clone + From<i64> + PartialEq> GradedLieConformalAlgebra<R>
    for FreeBosonsLieConformalAlgebra<R>
{
    fn generator_degree(&self, index: usize) -> Option<Degree> {
        self.graded.generator_degree(index)
    }

    fn degree(&self, element: &Self::Element) -> Option<Degree> {
        if element.is_zero() {
            return Some(Degree::int(0));
        }

        // Return None for non-homogeneous elements
        None
    }
}

impl<R: Ring + Clone + From<i64> + PartialEq + std::ops::Add<Output = R> + std::ops::Mul<Output = R>>
    LambdaBracket<R, FreeBosonsLCAElement<R>> for FreeBosonsLieConformalAlgebra<R>
{
    /// Compute the λ-bracket, extending `[α_i_λ α_j] = λ(α_i, α_j)K` by
    /// sesquilinearity (`∂K = 0`). Keys are j-th products.
    fn lambda_bracket(
        &self,
        a: &FreeBosonsLCAElement<R>,
        b: &FreeBosonsLCAElement<R>,
    ) -> HashMap<usize, FreeBosonsLCAElement<R>> {
        central_valued_bracket(a, b, self.graded.ngens(), self.central_index, |i, j| {
            if i == self.central_index || j == self.central_index {
                None
            } else {
                Some((self.get_pairing(i, j), 1))
            }
        })
    }

    fn n_product(&self, a: &FreeBosonsLCAElement<R>, b: &FreeBosonsLCAElement<R>, n: usize)
        -> FreeBosonsLCAElement<R>
    {
        self.lambda_bracket(a, b)
            .get(&n)
            .cloned()
            .unwrap_or_else(|| LieConformalAlgebraElement::zero())
    }
}

impl<R: Ring + Clone + From<i64> + PartialEq + Display> Display
    for FreeBosonsLieConformalAlgebra<R>
{
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(
            f,
            "The free Bosons Lie conformal algebra with {} generator(s) over {}",
            self.ngens_noncentral,
            self.graded.base_ring()
        )?;

        if self.ngens_noncentral <= 5 {
            write!(f, ": (")?;
            for (i, name) in self.graded.generator_names().iter().enumerate() {
                if i > 0 {
                    write!(f, ", ")?;
                }
                write!(f, "{}", name)?;
            }
            write!(f, ")")?;
        }

        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_free_bosons_creation() {
        let lca: FreeBosonsLieConformalAlgebra<i64> =
            FreeBosonsLieConformalAlgebra::new(1, 2, None, None);

        assert_eq!(lca.ngens_noncentral(), 2);
        assert_eq!(lca.ngens(), Some(3)); // 2 + central element
        assert!(!lca.is_abelian());
    }

    #[test]
    fn test_free_bosons_identity_gram() {
        let lca: FreeBosonsLieConformalAlgebra<i64> =
            FreeBosonsLieConformalAlgebra::new(1, 2, None, None);

        // Identity Gram matrix
        assert_eq!(lca.get_pairing(0, 0), 1);
        assert_eq!(lca.get_pairing(0, 1), 0);
        assert_eq!(lca.get_pairing(1, 0), 0);
        assert_eq!(lca.get_pairing(1, 1), 1);
    }

    #[test]
    fn test_free_bosons_custom_gram() {
        let gram = vec![vec![2, 1], vec![1, 2]];
        let lca: FreeBosonsLieConformalAlgebra<i64> =
            FreeBosonsLieConformalAlgebra::new(1, 2, Some(gram), None);

        assert_eq!(lca.get_pairing(0, 0), 2);
        assert_eq!(lca.get_pairing(0, 1), 1);
        assert_eq!(lca.get_pairing(1, 0), 1);
        assert_eq!(lca.get_pairing(1, 1), 2);
    }

    #[test]
    fn test_free_bosons_generators() {
        let lca: FreeBosonsLieConformalAlgebra<i64> =
            FreeBosonsLieConformalAlgebra::new(1, 2, None, None);

        assert!(lca.generator(0).is_some()); // alpha0
        assert!(lca.generator(1).is_some()); // alpha1
        assert!(lca.generator(2).is_some()); // K
        assert!(lca.generator(3).is_none());
    }

    #[test]
    fn test_free_bosons_lambda_bracket() {
        let gram = vec![vec![2, 0], vec![0, 3]];
        let lca: FreeBosonsLieConformalAlgebra<i64> =
            FreeBosonsLieConformalAlgebra::new(1, 2, Some(gram), None);

        let alpha0 = lca.generator(0).unwrap();
        let alpha1 = lca.generator(1).unwrap();

        // [α0_λ α0] = λ(α0, α0)K = 2λK
        let bracket00 = lca.lambda_bracket(&alpha0, &alpha0);
        assert!(bracket00.contains_key(&1)); // λ^1 term exists
        let k = lca.generator(2).unwrap();
        assert_eq!(bracket00.len(), 1);
        assert_eq!(bracket00[&1].terms(), k.scalar_mul(&2).terms());

        // [α0_λ α1] = λ(α0, α1)K = 0 (orthogonal in Gram matrix)
        let bracket01 = lca.lambda_bracket(&alpha0, &alpha1);
        assert!(bracket01.is_empty() || bracket01.values().all(|v| v.is_zero()));

        // [α1_λ α1] = λ(α1, α1)K = 3λK, so the only product is
        // α1_(1) α1 = 1! · 3K = 3K.
        let bracket11 = lca.lambda_bracket(&alpha1, &alpha1);
        assert!(bracket11.contains_key(&1)); // λ^1 term exists
        assert_eq!(bracket11.len(), 1);
        assert_eq!(bracket11[&1].terms(), k.scalar_mul(&3).terms());
    }

    #[test]
    fn test_free_bosons_central_element_bracket() {
        let lca: FreeBosonsLieConformalAlgebra<i64> =
            FreeBosonsLieConformalAlgebra::new(1, 2, None, None);

        let k = lca.generator(2).unwrap(); // Central element
        let alpha0 = lca.generator(0).unwrap();

        // [K_λ α0] = 0 (central element)
        let bracket = lca.lambda_bracket(&k, &alpha0);
        assert!(bracket.is_empty() || bracket.values().all(|v| v.is_zero()));
    }

    #[test]
    fn test_free_bosons_sesquilinearity() {
        // Kac (2.7.4): (∂a)_(n) b = -n a_(n-1) b and a_(n)(∂b) = ∂(a_(n) b) + n a_(n-1) b.
        // With [α_λ α] = λK, ∂K = 0: (∂α)_(2) α = -2K, α_(2) (∂α) = 2K, nothing else.
        let lca: FreeBosonsLieConformalAlgebra<i64> =
            FreeBosonsLieConformalAlgebra::new(1, 1, None, None);
        let alpha = lca.generator(0).unwrap();
        let k = lca.generator(1).unwrap();
        let d_alpha = alpha.apply_derivation();

        let left = lca.lambda_bracket(&d_alpha, &alpha);
        assert_eq!(left.len(), 1);
        assert_eq!(left[&2].terms(), k.scalar_mul(&-2).terms());

        let right = lca.lambda_bracket(&alpha, &d_alpha);
        assert_eq!(right.len(), 1);
        assert_eq!(right[&2].terms(), k.scalar_mul(&2).terms());

        // Skew-symmetry [b_λ a] = -[a_{-λ-∂} b]: with a = ∂α, b = α,
        // -[∂α_{-λ} α] = -(-(-λ)·(-λ)) K = λ²K, i.e. α_(2)(∂α) = 2K, as above.
    }

    #[test]
    #[should_panic(expected = "is not a generator of this algebra")]
    fn test_free_bosons_rejects_foreign_basis_index() {
        let lca: FreeBosonsLieConformalAlgebra<i64> =
            FreeBosonsLieConformalAlgebra::new(1, 1, None, None);
        let alpha = lca.generator(0).unwrap();
        let foreign = LieConformalAlgebraElement::from_basis(GeneratorIndex::finite(7));
        let _ = lca.lambda_bracket(&alpha, &foreign);
    }

    #[test]
    fn test_free_bosons_zero() {
        let lca: FreeBosonsLieConformalAlgebra<i64> =
            FreeBosonsLieConformalAlgebra::new(1, 1, None, None);

        let zero = lca.zero();
        assert!(zero.is_zero());
    }

    #[test]
    fn test_free_bosons_with_custom_names() {
        let names = vec!["a".to_string(), "b".to_string(), "K".to_string()];
        let lca: FreeBosonsLieConformalAlgebra<i64> =
            FreeBosonsLieConformalAlgebra::new(1, 2, None, Some(names.clone()));

        assert_eq!(lca.generator_names()[0], "a");
        assert_eq!(lca.generator_names()[1], "b");
        assert_eq!(lca.generator_names()[2], "K");
    }

    #[test]
    #[should_panic(expected = "Gram matrix must be symmetric")]
    fn test_free_bosons_nonsymmetric_gram() {
        let gram = vec![vec![1, 2], vec![3, 1]]; // Not symmetric
        let _lca: FreeBosonsLieConformalAlgebra<i64> =
            FreeBosonsLieConformalAlgebra::new(1, 2, Some(gram), None);
    }

    #[test]
    #[should_panic(expected = "Gram matrix must have ngens rows")]
    fn test_free_bosons_wrong_gram_size() {
        let gram = vec![vec![1, 0], vec![0, 1]]; // 2x2 matrix but 3 generators
        let _lca: FreeBosonsLieConformalAlgebra<i64> =
            FreeBosonsLieConformalAlgebra::new(1, 3, Some(gram), None);
    }
}
